def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', None)

    # Identify alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', True):
            alive_opps.append(o)

    # If no opponents, take a safe minimal bid
    if not alive_opps:
        return max(0.0, min(float(my_status.get('budget', 0.0)), DAILY_SALARY * 0.4))

    # Read yesterday's bids from previous_trace for immediate reaction
    yesterday_bids = []
    yesterday_pressures = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev:
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass
            # If they were near death, treat as higher pressure
            hp_after = prev.get('hp_after', None)
            if hp_after is not None:
                try:
                    yesterday_pressures.append(float(hp_after))
                except Exception:
                    pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    # Supply-driven base: if supply is tight, bid more; if plentiful, bid less.
    # supply in [15,25]; our need is 13.
    # When supply is near 15, competition likely higher.
    tightness = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        tightness = (float(supply) - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY)
    # tightness: 0 => min supply (15), 1 => max supply (25)
    # Convert to urgency: 1 when tight, 0 when abundant
    urgency = 1.0 - max(0.0, min(1.0, tightness))

    # If others were bidding extremely high yesterday, they likely tried to secure water aggressively.
    # We can undercut slightly while still ensuring we win when our hp is low.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Aggressive field: bid enough to not lose, but avoid burning budget.
        if my_hp <= 2.0 or my_no_water_days >= 2:
            target = DAILY_SALARY * (0.70 + 0.20 * urgency)
        else:
            target = DAILY_SALARY * (0.45 + 0.20 * urgency)
    else:
        # Moderate field: bid around a fraction of salary scaled by urgency and our condition.
        if my_hp <= 2.0 or my_no_water_days >= 2:
            target = DAILY_SALARY * (0.75 + 0.15 * urgency)
        else:
            target = DAILY_SALARY * (0.50 + 0.20 * urgency)

    # Budget cap and floor: never exceed budget, and keep some reserve.
    reserve_factor = 0.25
    max_affordable = max(0.0, my_budget)

    # If budget is low, bid close to remaining budget but still keep a small reserve.
    if my_budget <= DAILY_SALARY * 0.6:
        bid = max(0.0, min(max_affordable, my_budget * 0.85))
    else:
        bid = min(max_affordable, max(0.0, target))

    # Additional undercut heuristic: if yesterday's highest bid is far above our target,
    # we can slightly reduce to avoid overpaying.
    if highest_prev_bid > 0.0 and highest_prev_bid > bid * 1.8:
        bid = bid * 0.9

    # Ensure bid is non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    low_req_bids = []
    high_req_bids = []
    danger_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if isinstance(bid, (int, float)):
                prev_bids.append(float(bid))
                if opp.get('water_requirement', 0) <= WATER_REQ:
                    low_req_bids.append(float(bid))
                else:
                    high_req_bids.append(float(bid))
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                danger_opponents += 1

    if not alive:
        return float(min(budget, 18.0))

    scarcity = supply / float(WATER_REQ)
    severe_need = hp <= 2 or no_water >= 2
    moderate_need = hp <= 4 or no_water >= 1

    if low_req_bids:
        ref = max(low_req_bids)
    elif prev_bids:
        ref = min(max(prev_bids), 35.0)
    else:
        ref = 20.0

    if scarcity < 2.0:
        base = ref + 8.0
    elif scarcity < 2.5:
        base = ref + 3.0
    else:
        base = max(16.0, ref - 1.5)

    if danger_opponents >= 2:
        base += 3.0
    elif danger_opponents == 0 and scarcity >= 2.5:
        base -= 1.0

    if severe_need:
        bid = max(base, 58.0)
    elif moderate_need:
        bid = max(base, 34.0)
    else:
        bid = max(15.0, min(base, 28.0))

    if day >= 8 and hp >= 6 and budget < DAILY_SALARY * 2:
        bid = min(bid, 24.0)

    if budget < 25:
        bid = max(0.0, min(budget, max(12.0, budget * 0.9)))
    else:
        bid = min(budget, bid)

    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    if yesterday_bids:
        avg_prev = sum(yesterday_bids) / len(yesterday_bids)
        # Want to slightly outbid if needed
        target = avg_prev + 2.0
    else:
        target = DAILY_SALARY * 0.5
    # Adjust based on health
    hp = my_status['hp']
    if hp <= 2:
        desired = max(DAILY_SALARY * 0.8, target)
    elif hp <= 4:
        desired = max(DAILY_SALARY * 0.4, target)
    else:
        desired = min(DAILY_SALARY * 0.3, target)
    # Ensure we don't bid more than budget
    return min(my_status['budget'], desired)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], WATER_REQ * 1.0)

    supply = day_context['supply']
    num_winners_possible = int(supply // WATER_REQ)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.5
    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 1.2
    elif my_status['hp'] <= 5:
        base_bid = DAILY_SALARY * 0.9

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if num_winners_possible <= 1:
            if my_status['hp'] <= 3:
                base_bid = max(base_bid, highest_prev_bid * 1.1 + 5)
            else:
                base_bid = max(base_bid, highest_prev_bid * 1.05 + 2)
        elif num_winners_possible <= len(alive_opponents) / 2 + 1:
            if my_status['hp'] <= 2:
                base_bid = max(base_bid, highest_prev_bid * 1.08 + 3)
            else:
                base_bid = max(base_bid, highest_prev_bid * 1.02 + 1)
        else:
            if my_status['hp'] <= 1:
                base_bid = max(base_bid, highest_prev_bid * 1.05 + 1)
            else:
                base_bid = max(base_bid, highest_prev_bid * 0.95)

    day = day_context['day']
    if day >= EPISODE_DAYS - 2:
        if my_status['hp'] <= 3:
            base_bid = max(base_bid, DAILY_SALARY * 1.3)
        else:
            base_bid = max(base_bid, DAILY_SALARY * 1.0)

    final_bid = max(1.0, base_bid)
    return min(my_status['budget'], final_bid)
